#!/usr/bin/env python3
"""fits-audit §8: the measurement that admitted Tier 2 (issue #59).

This is the instrument for [docs/fits-audit.md](../docs/fits-audit.md#8-the-measurement-and-the-rule-fixed-in-advance).
It is not part of the build and not a dependency of the crate; it exists so the
numbers in the audit can be reproduced.

    python3 -m venv /tmp/v && /tmp/v/bin/pip install numpy astropy
    /tmp/v/bin/python .github/scripts/fits-measure.py --root /tmp/corpus --out /tmp/fits.jsonl

The corpus is **not** fetched here. `--root` holds a tree that
`.github/scripts/measure-fetch.py` produced from pinned codeload archives and
described in a per-file manifest, and `--manifest` makes this script read exactly
the files that manifest names — no `glob` of whatever happens to be on disk:

    python3 .github/scripts/measure-fetch.py --root /tmp/corpus --manifest /tmp/corpus/manifest.json
    /tmp/v/bin/python .github/scripts/fits-measure.py --root /tmp/corpus \
        --manifest /tmp/corpus/manifest.json --out /tmp/fits.jsonl

Pinned at the full commits the audit quotes: astropy
`dbbf2acd6dbb177db184bff319d2a2950dd178bb`, cfitsio
`113781d8aa442cf8d3c27295d9084674b8b039f2`, drizzlepac
`635834581ea2b226a3f3028b6ac54efb5e180dfc`, reproject
`9dddd419111a9ca159baaf7d5e2eb5729b447b58`.

The earlier instruction here was `git clone --depth 1` of a default branch, which
does **not** contain the commit the audit quotes, and `git fetch origin <sha>`,
which GitHub refuses (no arbitrary SHA is a ref). That is why the acquisition
moved to codeload-at-a-SHA plus a SHA-256 and a manifest — see issue #72.

The reference candidate remains generated by Astropy's `CompImageHDU` path.
Its compressed image payload is unchanged; the wrapper now preserves original
literal cards through the matching `Z*` metadata and copies every untransformed
HDU byte-for-byte. The external fixed #59 gate still supplies `fitsverify` and
`funpack -C` evidence. `fpack` is a separate reader-path control, never a bitwise
floating-point oracle or a source of reference-candidate payloads.

Two things the audit insists on, and this script honours:

* `GZIP_2` shuffles bytes in **decreasing** order of significance (convention §6.2),
  which is what CFITSIO implements;
* the tile payload is a **gzip** member (RFC 1952, CRC-32 and `ISIZE`), not zlib —
  so re-decompressing a tile here uses `gzip`, and a `zlib` prefix check would be
  wrong.
"""

import argparse
import glob
import gzip
import hashlib
import json
import os
import tempfile
from collections import Counter
from pathlib import Path

import numpy as np
from astropy.io import fits

CORPORA = (
    ("astropy", "astropy", "astropy/io/fits/tests/data"),
    ("cfitsio", "cfitsio", ""),
    ("drizzlepac", "drizzlepac", ""),
    ("reproject", "reproject", ""),
)

#: Keywords the compressed form cannot carry back; skipped in the header comparison.
SKIP = {"", "EXTNAME", "SIMPLE", "XTENSION", "BITPIX", "NAXIS", "NAXIS1", "NAXIS2",
        "NAXIS3", "NAXIS4", "PCOUNT", "GCOUNT", "EXTEND", "BSCALE", "BZERO", "TFIELDS",
        "CHECKSUM", "DATASUM", "COMMENT", "HISTORY", "ZIMAGE", "ZCMPTYPE", "ZBITPIX",
        "ZNAXIS", "ZNAXIS1", "ZNAXIS2", "ZNAXIS3", "ZTILE1", "ZTILE2", "ZNAME1",
        "ZVAL1", "THEAP"}


def eligible(hdu):
    """An uncompressed image HDU the handler would turn into a compressed table."""
    if not isinstance(hdu, (fits.PrimaryHDU, fits.ImageHDU)):
        return False
    if hdu.data is None or hdu.header.get("NAXIS", 0) < 1:
        return False
    return not hdu.header.get("GROUPS")


def eligible_count(path):
    """The denominator: how many image HDUs a correct rebuild has to carry.

    One definition, used by the instrument and by the tests that guard it, so that
    "every image HDU was processed" cannot be answered by two different counts.
    """
    with fits.open(path) as hdul:
        return sum(1 for h in hdul if eligible(h))


def sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        while chunk := stream.read(1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def _card_keyword(card):
    return card[:8].decode("ascii", errors="replace").strip(" ")


def _header_cards(raw_header):
    """Split one raw header record sequence at its literal END card."""
    cards = []
    for start in range(0, len(raw_header), 80):
        card = raw_header[start : start + 80]
        if len(card) != 80:
            raise RuntimeError("truncated FITS header card while preserving reference candidate")
        cards.append(card)
        if card[:8] == b"END     ":
            return cards, raw_header[start + 80 :]
    raise RuntimeError("FITS header has no literal END card while preserving reference candidate")


def _mapped_image_card(keyword):
    fixed = {
        "SIMPLE": "ZSIMPLE",
        "XTENSION": "ZTENSION",
        "BITPIX": "ZBITPIX",
        "NAXIS": "ZNAXIS",
        "EXTEND": "ZEXTEND",
        "BLOCKED": "ZBLOCKED",
        "PCOUNT": "ZPCOUNT",
        "GCOUNT": "ZGCOUNT",
        "CHECKSUM": "ZHECKSUM",
        "DATASUM": "ZDATASUM",
    }
    if keyword in fixed:
        return fixed[keyword]
    if keyword.startswith("NAXIS") and keyword[5:].isdigit():
        return "Z" + keyword
    return None


def _is_image_structural_card(keyword):
    return (
        keyword in {"SIMPLE", "XTENSION", "BITPIX", "NAXIS", "EXTEND", "BLOCKED", "PCOUNT", "GCOUNT"}
        or (keyword.startswith("NAXIS") and keyword[5:].isdigit())
    )


def _hdu_layouts(path):
    """Return each HDU's start, data start and padded end without reading its payload."""
    layouts = []
    with fits.open(path, disable_image_compression=True, memmap=False) as hdul:
        for hdu in hdul:
            start = int(hdu._header_offset)
            if hdu._data_offset is None:
                header_length = len(hdu.header.tostring().encode("ascii"))
                data_start = start + header_length
            else:
                data_start = int(hdu._data_offset)
            data_size = int(hdu._data_size or 0)
            end = data_start + ((data_size + 2879) // 2880) * 2880
            layouts.append((start, data_start, end))
    return layouts


def _read_range(stream, start, end):
    stream.seek(start)
    value = stream.read(end - start)
    if len(value) != end - start:
        raise RuntimeError("short read while preserving reference FITS HDU bytes")
    return value


def _copy_range(source_stream, destination_stream, start, end):
    source_stream.seek(start)
    remaining = end - start
    while remaining:
        block = source_stream.read(min(1024 * 1024, remaining))
        if not block:
            raise RuntimeError("short copy while preserving an unchanged FITS HDU")
        destination_stream.write(block)
        remaining -= len(block)


def _repair_compressed_header(source_header, candidate_header, product_id):
    """Rebuild header metadata while retaining every original literal card.

    Original structural cards are represented by their FITS tiled-image `Z*`
    counterparts. Their complete 80-byte images are moved without parsing or
    normalizing any field. Other original cards, including duplicate COMMENT,
    HISTORY, blank, CHECKSUM and DATASUM cards, are replayed in source order. If
    Astropy omitted an otherwise unambiguous source user card, restore its exact
    raw image; a same-key card with a different value remains a hard error.
    Missing/ambiguous structural mappings are never silently filtered.
    """
    source_cards, _source_padding = _header_cards(source_header)
    candidate_cards, candidate_padding = _header_cards(candidate_header)
    if not candidate_cards or candidate_cards[-1][:8] != b"END     ":
        raise RuntimeError(f"{product_id}: compressed reference candidate has no terminal END card")

    replay_cards = []
    replay_indices = set()
    for source_card in source_cards:
        keyword = _card_keyword(source_card)
        if keyword == "END":
            continue
        target_keyword = _mapped_image_card(keyword)
        if target_keyword is not None:
            matches = [
                index for index, candidate_card in enumerate(candidate_cards[:-1])
                if _card_keyword(candidate_card) == target_keyword
            ]
            if len(matches) != 1:
                raise RuntimeError(
                    f"{product_id}: expected exactly one {target_keyword} for literal source {keyword} card; "
                    f"found {len(matches)}"
                )
            target_index = matches[0]
            # Change only the keyword field. The original value, spacing, comment
            # and all 80 card bytes remain otherwise untouched.
            target_card = target_keyword.encode("ascii").ljust(8, b" ") + source_card[8:]
            candidate_cards[target_index] = target_card
            if keyword in {"CHECKSUM", "DATASUM"}:
                if target_index in replay_indices:
                    raise RuntimeError(f"{product_id}: duplicated source checksum mapping for {target_keyword}")
                replay_indices.add(target_index)
                replay_cards.append(target_card)
            continue

        if _is_image_structural_card(keyword):
            raise RuntimeError(f"{product_id}: no exact tiled-image mapping for structural card {keyword}")

        available = [
            (index, candidate_card)
            for index, candidate_card in enumerate(candidate_cards[:-1])
            if index not in replay_indices and _card_keyword(candidate_card) == keyword
        ]
        exact = [index for index, candidate_card in available if candidate_card == source_card]
        match = exact[0] if exact else None
        if match is None and available:
            try:
                source_value = fits.Card.fromstring(source_card.decode("ascii")).value
            except Exception as error:
                raise RuntimeError(f"{product_id}: cannot parse source {keyword or 'blank'} card: {error}") from error
            equivalent = []
            for index, candidate_card in available:
                try:
                    candidate_value = fits.Card.fromstring(candidate_card.decode("ascii")).value
                except Exception:
                    continue
                if candidate_value == source_value:
                    equivalent.append(index)
            if len(equivalent) == 1:
                match = equivalent[0]
            elif len(equivalent) > 1:
                raise RuntimeError(
                    f"{product_id}: ambiguous value-equivalent candidate cards for source keyword {keyword!r}"
                )
            elif available:
                raise RuntimeError(
                    f"{product_id}: candidate contains {keyword!r} cards with values different from the source"
                )

        if match is None:
            # The writer omitted this non-structural source card. Restore its
            # literal bytes; the strict post-funpack comparator still checks the
            # resulting complete header and storage payload without exceptions.
            replay_cards.append(source_card)
            continue
        if match in replay_indices:
            raise RuntimeError(f"{product_id}: one candidate card ambiguously represents multiple source cards")
        candidate_cards[match] = source_card
        replay_indices.add(match)
        replay_cards.append(source_card)

    prefix = [
        card for index, card in enumerate(candidate_cards[:-1])
        if index not in replay_indices
    ]
    end_card = candidate_cards[-1]
    card_bytes = b"".join(prefix + replay_cards + [end_card])
    required_records = ((len(card_bytes) + 2879) // 2880) * 2880
    repaired_length = max(len(candidate_header), required_records)
    if repaired_length % 2880:
        raise RuntimeError(f"{product_id}: repaired FITS header length is not a whole FITS record")
    padding_length = repaired_length - len(card_bytes)
    if padding_length < 0:
        raise RuntimeError(f"{product_id}: repaired FITS header exceeds its computed record length")
    if repaired_length == len(candidate_header) and padding_length == len(candidate_padding):
        padding = candidate_padding
    else:
        padding = b" " * padding_length
    return card_bytes + padding


def _preserve_reference_hdu_bytes(source_path, candidate_path, output_entries):
    """Keep non-image HDUs byte-identical and repair compressed headers in place.

    Compressed payloads are copied byte-for-byte from the Astropy-generated
    candidate. Untransformed source HDUs are copied as raw FITS records rather
    than reserialized, so their original CHECKSUM/DATASUM remain valid.
    """
    source_layouts = _hdu_layouts(source_path)
    candidate_layouts = _hdu_layouts(candidate_path)
    if len(candidate_layouts) != len(output_entries):
        raise RuntimeError(
            "Astropy candidate HDU count differs from the explicit source/candidate mapping: "
            f"{len(candidate_layouts)} != {len(output_entries)}"
        )
    if any(source_index >= len(source_layouts) for _kind, source_index in output_entries):
        raise RuntimeError("source/candidate HDU mapping contains an out-of-range source index")

    destination = Path(candidate_path)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="wb", prefix=f".{destination.name}.repair-", suffix=".tmp",
            dir=destination.parent, delete=False,
        ) as repaired_stream:
            temporary = Path(repaired_stream.name)
            with Path(source_path).open("rb") as source_stream, destination.open("rb") as candidate_stream:
                for output_index, (kind, source_index) in enumerate(output_entries):
                    candidate_start, candidate_data_start, candidate_end = candidate_layouts[output_index]
                    if kind == "unchanged_source":
                        source_start, _source_data_start, source_end = source_layouts[source_index]
                        _copy_range(source_stream, repaired_stream, source_start, source_end)
                    elif kind in {"synthetic_primary", "compressed_image"}:
                        if kind == "compressed_image":
                            source_start, source_data_start, _source_end = source_layouts[source_index]
                            source_header = _read_range(source_stream, source_start, source_data_start)
                            candidate_header = _read_range(candidate_stream, candidate_start, candidate_data_start)
                            fixed_header = _repair_compressed_header(
                                source_header, candidate_header, Path(source_path).name
                            )
                            repaired_stream.write(fixed_header)
                            _copy_range(candidate_stream, repaired_stream, candidate_data_start, candidate_end)
                        else:
                            _copy_range(candidate_stream, repaired_stream, candidate_start, candidate_end)
                    else:
                        raise RuntimeError(f"unknown FITS reference HDU mapping kind: {kind}")
        os.replace(temporary, destination)
        temporary = None
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def _prepare_compressed_header(comp_hdu, source_hdu):
    """Carry source comments/omitted cards into Astropy's logical header view."""
    source_header = source_hdu.header
    candidate_header = comp_hdu.header
    for card in source_header.cards:
        keyword = card.keyword
        if keyword in candidate_header:
            candidate_header.comments[keyword] = card.comment
        elif keyword in {"EXTEND", "BLOCKED", "PCOUNT", "GCOUNT", "BLANK", "BSCALE", "BZERO"}:
            candidate_header.set(keyword, source_header[keyword], card.comment)


def rebuild(path, out):
    """Compress each eligible image with Astropy while retaining exact FITS cards.

    Astropy remains the reference payload writer and the compression settings are
    unchanged. Structural-card comments/values are carried through their `Z*`
    counterparts, source header cards are replayed literally in original order,
    and untransformed HDUs are copied byte-for-byte. The mapping from original to
    candidate index is returned rather than assumed.
    """
    output_entries = []
    with fits.open(path, memmap=False, do_not_scale_image_data=True, uint=False) as hdul:
        new, mapping = [], []
        for idx, h in enumerate(hdul):
            if eligible(h):
                data = np.asarray(h.data)
                ctype = "GZIP_1" if data.dtype.kind in "iu" else "GZIP_2"
                if idx == 0:
                    new.append(fits.PrimaryHDU())
                    output_entries.append(("synthetic_primary", idx))
                comp = fits.CompImageHDU(
                    data=data, header=h.header.copy(), compression_type=ctype, quantize_level=0
                )
                _prepare_compressed_header(comp, h)
                new.append(comp)
                candidate_index = len(new) - 1
                output_entries.append(("compressed_image", idx))
                mapping.append((idx, candidate_index))
            elif h.data is not None:
                copy = h.copy()
                copy.data = np.array(h.data)
                new.append(copy)
                output_entries.append(("unchanged_source", idx))
            else:
                new.append(h.copy())
                output_entries.append(("unchanged_source", idx))
        fits.HDUList(new).writeto(out, overwrite=True)
    _preserve_reference_hdu_bytes(path, out, output_entries)
    return len(mapping), mapping

def verify(path, out, mapping):
    """Every image array identical bit for bit, and every carried keyword equal.

    The count is checked against the **source**, not against the caller's mapping.
    A mapping that quietly omits an eligible image HDU would otherwise leave that
    HDU unexamined and the file looking correct — which is exactly the shape of
    the bug this measurement once had: a numerator that shrinks with the work.
    """
    with fits.open(path) as a, fits.open(out) as b:
        if len(b) < len(a):
            return False, "hdu_count"
        expected = eligible_count(path)
        covered = {orig for orig, _ in mapping}
        if len(mapping) != expected or len(covered) != expected:
            return False, "images_%d_of_%d" % (len(covered), expected)
        for orig, cand in mapping:
            ha, hb = a[orig], b[cand]
            da, db = np.asarray(ha.data), np.asarray(hb.data)
            # `equal_nan` because NaN is not equal to itself, and a science array
            # full of NaN must not look like a difference of content.
            if da.shape != db.shape or not np.array_equal(da, db, equal_nan=da.dtype.kind == "f"):
                return False, "array_%d" % orig
            for key, value in ha.header.items():
                if key in SKIP or key not in hb.header:
                    continue
                try:
                    if hb.header[key] != value:
                        return False, "keyword_%s" % key
                except Exception:               # noqa: BLE001
                    continue
    return True, "ok"


def tiles(path):
    """Every tile payload of every compressed HDU, as raw bytes."""
    out = []
    with fits.open(path, disable_image_compression=True) as hdul:
        for hdu in hdul:
            if not hdu.header.get("ZIMAGE"):
                continue
            names = [c for c in hdu.columns.names if "COMPRESSED_DATA" in c.upper()]
            if names:
                out.extend(bytes(bytearray(row)) for row in hdu.data[names[0]])
    return out


def recompress(payloads, level=9):
    """Tier 1: what re-deflating the existing gzip members would save."""
    old = new = 0
    for tile in payloads:
        old += len(tile)
        try:
            plain = gzip.decompress(tile)
        except OSError:
            return None
        new += min(len(tile), len(gzip.compress(plain, compresslevel=level, mtime=0)))
    return old, new


def from_manifest(path):
    """(corpus, absolute path) for every FITS file the manifest names.

    The manifest is the single acquisition authority: a file it does not name is
    not measured, and a file it names that is missing is an error rather than a
    quietly smaller corpus.
    """
    with open(path) as f:
        manifest = json.load(f)
    out = []
    for corpus in manifest["corpora"]:
        if corpus["format"] != "fits":
            continue
        for row in corpus["entries"]:
            out.append((corpus["name"], row["path"], row))
    return manifest, out


def main():
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--root", default="/tmp/corpus")
    ap.add_argument("--manifest", default="", help="per-file manifest from measure-fetch.py")
    ap.add_argument("--out", default="/tmp/fits.jsonl")
    ap.add_argument(
        "--candidate-dir", default="",
        help="retain the exact per-row reference candidates here for external validation",
    )
    args = ap.parse_args()

    candidate_dir = Path(args.candidate_dir).resolve() if args.candidate_dir else None
    if candidate_dir is not None:
        candidate_dir.mkdir(parents=True, exist_ok=True)

    if args.manifest:
        manifest, files = from_manifest(args.manifest)
        corpora = [(name, "", [(path, row)]) for name, path, row in files]
        print("manifest digest %s, %d FITS files" % (manifest["manifest_digest"], len(files)))
    else:
        corpora = []
        for corpus, repo, sub in CORPORA:
            root = os.path.join(args.root, repo)
            if not os.path.isdir(root):
                print("missing checkout:", root)
                continue
            for path in sorted(glob.glob(os.path.join(root, sub, "**", "*.fit*"), recursive=True)):
                if path.lower().endswith((".fits", ".fit", ".fts")):
                    corpora.append((corpus, path, [(path, None)]))

    rows, seen = [], set()
    for corpus, single, batch in corpora:
        for path, recorded in batch:
            path = path if os.path.isabs(path) else os.path.join(args.root, path)
            if recorded is not None:
                size = os.path.getsize(path)
                if size != recorded["bytes"]:
                    raise SystemExit(
                        "%s is %d bytes, the manifest says %d — run measure-fetch.py --verify"
                        % (path, size, recorded["bytes"])
                    )
                observed_sha = sha256_file(path)
                if observed_sha != recorded["sha256"]:
                    raise SystemExit(
                        "%s SHA-256 is %s, the fixed manifest says %s — refusing a changed source"
                        % (path, observed_sha, recorded["sha256"])
                    )
            if path in seen:
                continue
            seen.add(path)
            size = os.path.getsize(path)
            row = {"corpus": corpus, "path": path, "bytes": size}
            if recorded is not None:
                row["manifest_path"] = recorded["path"]
                row["manifest_sha256"] = recorded["sha256"]
            try:
                with fits.open(path) as hdul:
                    n = sum(1 for h in hdul if eligible(h))
                    codecs = sorted({str(h.header.get("ZCMPTYPE", "")).strip().strip("'")
                                     for h in hdul if h.header.get("ZIMAGE")})
            except Exception:                   # noqa: BLE001
                rows.append({**row, "status": "refused", "reason": "unreadable"})
                continue
            if n == 0:
                rows.append({**row, "status": "refused",
                             "reason": "other_codec:" + ",".join(codecs) if codecs else "no_image"})
                continue

            if candidate_dir is None:
                out = Path("/tmp/fits-measure.fits")
            else:
                candidate_id = recorded.get("product_id") if isinstance(recorded, dict) else None
                candidate_id = candidate_id or Path(path).stem
                safe_id = "".join(character if character.isalnum() or character in "-_." else "_"
                                   for character in candidate_id)
                out = candidate_dir / f"{safe_id}.reference.fits"
            try:
                images, mapping = rebuild(path, str(out))
            except Exception as e:              # noqa: BLE001
                rows.append({**row, "status": "refused", "reason": "cannot_compress",
                             "err": str(e)})
                continue
            new_size = out.stat().st_size
            if candidate_dir is not None:
                row["reference_candidate"] = {
                    "product_id": recorded.get("product_id") if isinstance(recorded, dict) else None,
                    "filename": out.name,
                    "bytes": new_size,
                    "sha256": sha256_file(out),
                    "source_bytes": size,
                    "source_sha256": sha256_file(path),
                    "generation": "Astropy CompImageHDU reference; literal source cards preserved by rebuild()",
                    "generation_method": "GZIP_1 for integer arrays; GZIP_2 for floating arrays; quantize_level=0",
                    "header_preservation": "raw 80-byte source cards mapped/replayed; untransformed HDUs copied byte-for-byte",
                    "eligible_images": images,
                    "mapping": mapping,
                }
            ok, why = verify(path, str(out), mapping)
            result = recompress(tiles(str(out)))
            row.update(status="tier2", images=images, eligible_images=n, new_size=new_size,
                       pct=100.0 * (size - new_size) / size if size else 0.0,
                       exact=ok, why=why)
            if result:
                old, new = result
                row.update(tiles=len(tiles(out)), tile_bytes=old,
                           tier1_pct=100.0 * (old - new) / new_size if new_size else 0.0)
            rows.append(row)

    with open(args.out, "w") as f:
        for r in rows:
            f.write(json.dumps(r) + "\n")

    t2 = [r for r in rows if r["status"] == "tier2"]
    ok = [r for r in t2 if r["exact"]]
    print("files %d" % len(rows), Counter(r["status"] for r in rows))
    print("refusals", Counter(r["reason"] for r in rows if r["status"] == "refused").most_common())
    if ok:
        p = sorted(r["pct"] for r in ok)
        print("tier2 n=%d median %.2f q1 %.2f q3 %.2f share>0 %.0f%% max %.2f"
              % (len(p), p[len(p) // 2], p[len(p) // 4], p[3 * len(p) // 4],
                 100 * sum(1 for x in p if x > 0) / len(p), p[-1]))
        print("share of corpus %.1f%%" % (100 * len(ok) / len(rows)))
        t1 = sorted(r["tier1_pct"] for r in ok if "tier1_pct" in r)
        if t1:
            print("tier1 n=%d median %.2f max %.2f" % (len(t1), t1[len(t1) // 2], t1[-1]))
    print("verification failures:", [(r["why"], os.path.basename(r["path"]))
                                     for r in t2 if not r["exact"]])


if __name__ == "__main__":
    main()
